 ]
function get_type() {
    try {
        let varString = source.getVariable();
        //java.log("源变量原始数据: " + varString);

        if (varString=="") {
            java.toast("当前未设置来源，使用默认来源");
            var baseVariable = JSON.stringify({
	                     sourceType: "first",
	                     sourceName: "🐈猫眼①",
	                    	sourceAPI: "http://api.myweipin.com"
             }, null, "\t");
            source.setVariable(baseVariable);
            return;
        }

       let currentData = JSON.parse(varString);
        let currentSource = "未设置";

        for (let i = 0; i < data.length; i++) {
            if (data[i][1] === currentData.sourceType) {
                currentSource = data[i][0];
                break;
            }
        }

        java.toast(`当前来源: ${currentSource}`);
    } catch (e) {
        java.toast("模式数据解析错误: " + e.message);
        java.log("解析源变量出错: " + e);
    }
}
function Source(sourceType) {
    try {
        let validSource = false;
        let sourceName = "";
        let sourceAPI = "";

        for (let i = 0; i < data.length; i++) {
            if (data[i][1] === sourceType) {
                validSource = true;
                sourceName = data[i][0];
                sourceAPI = data[i][2];
                break;
            }
        }

        if (validSource) {
            var variable = {
                sourceType: sourceType,
                sourceName: sourceName,
                sourceAPI: sourceAPI
            };

            var jsonStr = JSON.stringify(variable, null, "\t");
            source.setVariable(jsonStr);
            java.toast(`✅ 已切换到: ${sourceName}`);
            java.log("设置源变量: " + jsonStr);
        } else {
            java.toast("❌ 无效来源");
        }
    } catch (e) {
        java.toast("切换来源出错: " + e.message);
        java.log("切换来源出错: " + e);
    }
}

